/* ==========================================================================
   Mi RCR — fuente.js
   Tipografía Outfit (Regular y Bold) empaquetada en base64 para pdfmake.
   pdfmake no usa las fuentes del navegador: necesita el TTF en su VFS.
   Subconjunto latino + acentos del español. Generada desde Outfit variable
   (Google Fonts, OFL). Se registra al vuelo cuando se genera un PDF de texto.
   ========================================================================== */

window.OUTFIT_TTF = {
  regular: "",
  bold: ""
};

/* Inyecta Outfit en el VFS de pdfmake y la deja como fuente por defecto. */
window.registrarOutfit = function () {
  if (!window.pdfMake) return false;
  if (window.__outfitListo) return true;
  pdfMake.vfs = pdfMake.vfs || {};
  pdfMake.vfs['Outfit-Regular.ttf'] = window.OUTFIT_TTF.regular;
  pdfMake.vfs['Outfit-Bold.ttf']    = window.OUTFIT_TTF.bold;
  pdfMake.fonts = pdfMake.fonts || {};
  pdfMake.fonts.Outfit = {
    normal: 'Outfit-Regular.ttf',
    bold: 'Outfit-Bold.ttf',
    italics: 'Outfit-Regular.ttf',
    bolditalics: 'Outfit-Bold.ttf'
  };
  window.__outfitListo = true;
  return true;
};
